-- 755: слово «накладные» убрано из подписей Себестоимости (ВГ 24.10: понятные названия), только ru
update translations set ru = 'Зарплат, газа и света, хозрасходов в периоде нет' where key = 'cost_ov_none';
update translations set ru = 'Зарплаты, газ и свет, хозрасходы — расходы кухни, которые не относятся к конкретному блюду: зарплаты, газ, свет, вода, оборудование, хозтовары и прочее (берутся из финансов). Каждый расход делится поровну на все приёмы пищи за свой срок: зарплата — за месяц, покупка — за «Период расхода». Так получается цена одного приёма пищи; ретрит получает её столько раз, сколько приёмов пищи было у его участников. Исключение — расходы «на ретрит» (билеты, гонорары): они делятся только между участниками своего ретрита. Наведите на сумму — там расчёт по строке.' where key = 'cost_overhead_hint';
update translations set ru = 'Зарплаты и хозрасходы без вкушающих или без приёма пищи в меню (не распределены)' where key = 'cost_overhead_unallocated';
update translations set ru = 'Продукты по рецептам, посуда, готовое со стороны, плюс зарплаты, газ и свет, хозрасходы и расходы «на ретрит». Всё делится на фактических вкушающих.' where key = 'cost_subtitle';
update translations set ru = 'Не удалось загрузить зарплаты, газ и свет, хозрасходы — показаны только продукты и посуда' where key = 'cost_w_ov_error';
update translations set ru = 'Расходы «на ретрит» без ретрита и назначения считаются общими, назначьте их во вкладке «Зарплаты, газ и свет, хозрасходы»' where key = 'cost_w_ov_unassigned';
